const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
return $input.all().map(({json}) => {
 if (json.type === 'quote') {
  const days = daysSince(json.sent);
  const due = json.status === 'sent' && days >= 3;
  return {json: {...json, action:'quote_follow_up', days_open: days, needs_action: due, reason: json.status !== 'sent' ? `quote ${json.status}` : due ? `quote unanswered for ${days} days` : 'quote sent recently'}};
 }
 const days = daysSince(json.last_service);
 const due = days >= 335;
 return {json: {...json, action:'annual_maintenance', days_since_service: days, needs_action: due, reason: due ? 'annual maintenance due' : 'serviced recently'}};
});

return $input.all().map(({json}) => {
 const first = json.name.split(' ')[0];
 const message = json.action === 'quote_follow_up'
  ? `Hi ${first}, I wanted to check you received our quote for the ${json.job}. Any questions about the price or timing? Reply here and I will answer the same day. This message was prepared by an automated assistant.`
  : `Hi ${first}, your ${json.job} is due for its yearly service. Reply with a day that suits you and we will send a technician. This message was prepared by an automated assistant.`;
 const subject = json.action === 'quote_follow_up' ? `Your quote: ${json.job}` : `Yearly service for your ${json.job}`;
 return {json: {...json, channel:'email', to: json.email, subject, message, approval:'auto_send'}};
});
